def maxStackHeight(cuboids):
    c = sorted(sorted(box) for box in cuboids)
    n = len(c)
    dp = [0] * n
    for i in range(n):
        a, b, h = c[i]
        best = 0
        for j in range(i):
            x, y, z = c[j]
            if x <= a and y <= b and z <= h and dp[j] > best:
                best = dp[j]
        dp[i] = best + h
    return max(dp)
